package pe.farmagest.inventario.service;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.time.*;import java.util.*;import org.springframework.web.server.ResponseStatusException;
import pe.farmagest.inventario.repository.*;import pe.farmagest.inventario.entity.*;import pe.farmagest.inventario.security.JwtAuthenticationFilter.UserPrincipal;
class ConteoServiceTest {
 ConteoRepository sesiones;ConteoLineaRepository lineas;ConteoEventoRepository eventos;ConteoFotoRepository fotos;ProductoStockRepository stocks;MovimientoKardexRepository kardex;ConteoCatalogoClient catalogo;ConteoService service;ConteoFisico sesion;ConteoLinea linea;UserPrincipal user;
 @BeforeEach void setup(){sesiones=mock(ConteoRepository.class);lineas=mock(ConteoLineaRepository.class);eventos=mock(ConteoEventoRepository.class);fotos=mock(ConteoFotoRepository.class);stocks=mock(ProductoStockRepository.class);kardex=mock(MovimientoKardexRepository.class);catalogo=mock(ConteoCatalogoClient.class);service=new ConteoService(sesiones,lineas,eventos,fotos,stocks,kardex,catalogo);user=new UserPrincipal(8L,"almacen",1L,List.of("ROLE_ALMACENERO"));sesion=new ConteoFisico();sesion.id=1L;sesion.sucursalId=1;sesion.usuarioId=8L;sesion.referencia="Estante A";sesion.estado="ABIERTO";sesion.marcador=10L;linea=new ConteoLinea();linea.id=1L;linea.conteoId=1L;linea.productoId=5L;linea.stockInicial=50;linea.cantidad=45;linea.nombre="Producto";linea.actualizadoInicial=LocalDateTime.of(2026,10,27,10,0);when(sesiones.bloquear(1L)).thenReturn(Optional.of(sesion));when(lineas.findByConteoIdOrderByIdAsc(1L)).thenReturn(List.of(linea));when(eventos.findByConteoIdOrderByIdAsc(1L)).thenReturn(List.of());}
 ProductoStock stock(int n){var p=new ProductoStock(5L,1,n,0,100);p.setActualizadoEn(linea.actualizadoInicial);return p;}
 @Test void openCountNeverRevealsExpectedOrDifference(){var dto=service.ver(1L,user);assertNull(dto.lineas().get(0).esperado());assertNull(dto.lineas().get(0).diferencia());assertNull(dto.lineas().get(0).resultado());}
 @Test void noMovementsProducesShortageAndNeverChangesStock(){when(stocks.bloquearSucursal(1)).thenReturn(List.of(stock(50)));when(kardex.ultimoIdProducto(1,5L)).thenReturn(10L);var dto=service.cerrar(1L,user);assertEquals("FALTANTE",dto.lineas().get(0).resultado());assertEquals(-5L,dto.lineas().get(0).diferencia());assertEquals(50,dto.lineas().get(0).esperado());verify(stocks,never()).save(any());verify(kardex,never()).save(any());}
 @Test void netZeroMovementsStillRequireRecount(){assertEquals("REQUIERE_RECONTEO",ConteoService.resultado(linea,stock(50),12,10));when(stocks.bloquearSucursal(1)).thenReturn(List.of(stock(50)));when(kardex.ultimoIdProducto(1,5L)).thenReturn(12L);var dto=service.cerrar(1L,user);assertNull(dto.lineas().get(0).diferencia());assertNull(dto.lineas().get(0).esperado());}
 @Test void stockChangeWithoutKardexAlsoRequiresRecount(){assertEquals("REQUIERE_RECONTEO",ConteoService.resultado(linea,stock(47),10,10));var p=stock(50);p.setActualizadoEn(linea.actualizadoInicial.plusSeconds(1));assertEquals("REQUIERE_RECONTEO",ConteoService.resultado(linea,p,10,10));}
 @Test void exactAndExcessClassified(){linea.cantidad=50;assertEquals("CONFORME",ConteoService.resultado(linea,stock(50),10,10));linea.cantidad=52;assertEquals("SOBRANTE",ConteoService.resultado(linea,stock(50),10,10));}
 @Test void anotherBranchAndOtherCounterCannotEdit(){var otro=new UserPrincipal(9L,"otro",2L,List.of("ROLE_ALMACENERO"));assertEquals(403,assertThrows(ResponseStatusException.class,()->service.ver(1L,otro)).getStatusCode().value());var sameBranch=new UserPrincipal(9L,"otro",1L,List.of("ROLE_ALMACENERO"));assertThrows(ResponseStatusException.class,()->service.contar(1L,5L,4,"",sameBranch,"hidden"));verifyNoInteractions(catalogo);}
 @Test void closedCountsAreImmutable(){sesion.estado="FINALIZADO";assertThrows(ResponseStatusException.class,()->service.contar(1L,5L,4,"",user,"hidden"));assertThrows(ResponseStatusException.class,()->service.cerrar(1L,user));verifyNoInteractions(catalogo);}
 @Test void negativeAndEmptyCountsRejected(){assertThrows(ResponseStatusException.class,()->service.contar(1L,5L,-1,"",user,"hidden"));when(lineas.findByConteoIdOrderByIdAsc(1L)).thenReturn(List.of());assertThrows(ResponseStatusException.class,()->service.cerrar(1L,user));}
 @Test void editingCountUsesCatalogIdentityAndPreservesAudit(){when(catalogo.obtener(5L,"hidden")).thenReturn(new ConteoCatalogoClient.Producto(5L,"Nombre real","0012345678905","Unidad"));when(lineas.findByConteoIdAndProductoId(1L,5L)).thenReturn(Optional.of(linea));service.contar(1L,5L,0,"Segundo recuento",user,"hidden");assertEquals(0,linea.cantidad);assertEquals("Nombre real",linea.nombre);assertEquals("0012345678905",linea.codigo);verify(eventos).save(argThat(e->e.detalle.contains("45 → 0")&&e.usuarioId.equals(8L)));verify(stocks,never()).save(any());}
 @Test void onlyAdministratorCanRecordReview(){sesion.estado="FINALIZADO";assertThrows(ResponseStatusException.class,()->service.revisar(1L,"Reconteo solicitado",user));var admin=new UserPrincipal(1L,"admin",1L,List.of("ROLE_ADMINISTRADOR"));var dto=service.revisar(1L,"Reconteo solicitado",admin);assertEquals(1L,dto.revisadoPor());assertThrows(ResponseStatusException.class,()->service.revisar(1L,"Cambiar evidencia",admin));}
 @Test void photoRejectsInvalidContent(){assertThrows(ResponseStatusException.class,()->ConteoService.validarFoto("<script>".getBytes(),"image/png"));assertThrows(ResponseStatusException.class,()->ConteoService.validarFoto(new byte[9*1024*1024],"image/jpeg"));}
}
